import{_ as i,a0 as p,w as a,s as u,ao as d,I as n,x as e,a1 as t,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse(`{"title":"Linux有问必答——如何修复Google Chrome 的“Your profile could not be opened correctly”错误 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答——如何修复Google Chrome 的“Your profile could not be opened correctly”错误 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答——如何修复Google Chrome 的“Your profile could not be opened correctly”错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答——如何修复Google Chrome 的“Your profile could not be opened correctly”错误 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150203 Linux FAQs with Answers--How to fix 'Your profile could not be opened correctly' on Google Chrome","title":"Linux有问必答——如何修复Google Chrome 的“Your profile could not be opened correctly”错误","tag":"201502","desc":""},"relativePath":"201502/20150203 Linux FAQs with Answers--How to fix 'Your profile could not be opened correctly' on Google Chrome.md","filePath":"[post].md"}`),c={name:"201502/20150203 Linux FAQs with Answers--How to fix 'Your profile could not be opened correctly' on Google Chrome.md"};function m(s,o,f,g,h,C){const r=p("Link");return a(),u("div",null,[o[11]||(o[11]=d(`<h1 id="linux有问必答——如何修复google-chrome-的-your-profile-could-not-be-opened-correctly-错误" tabindex="-1">Linux有问必答——如何修复Google Chrome 的“Your profile could not be opened correctly”错误 <a class="header-anchor" href="#linux有问必答——如何修复google-chrome-的-your-profile-could-not-be-opened-correctly-错误" aria-label="Permalink to “Linux有问必答——如何修复Google Chrome 的“Your profile could not be opened correctly”错误”">​</a></h1><blockquote><p><strong>提问</strong>：当我在linux打开Google Chrome 浏览器时，我已经几次收到弹出窗口，提示我的档案文件没有被正确打开（Your profile could not be opened correctly.）。每次我打开Chrome都要弹出来，我应该如何修复这个问题？</p></blockquote><p>当你在你的Chrome上看见&quot;Your profile could not be opened correctly&quot;错误信息时，从某种程度上讲，那是因为你的Chrome配置文件数据已经损坏。这个问题经常发生在手动升级Google Chrome的时候。</p><p><img src="https://farm8.staticflickr.com/7428/16238502737_27bdda6685_o.png" alt=""></p><p>修复取决于到底哪个文件损坏，你可以试试下面的几个方法。</p><h3 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to “方法一”">​</a></h3><p>关掉所有Chrome窗口和标签页。</p><p>进入~/.config/google-chrome/Default，移除或者重命名&quot;Web Data&quot;文件。</p><pre><code>$ cd ~/.config/google-chrome/Default
$ rm &quot;Web Data&quot; 
</code></pre><p>再次开打Google Chrome浏览器。</p><h3 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to “方法二”">​</a></h3><p>关掉所有Chrome窗口和标签页。</p><p>进入~/.config/google-chrome/&quot;Profile 1&quot;，并重命名&quot;History&quot;文件。</p><pre><code>$ cd ~/.config/google-chrome/&quot;Profile 1&quot;
$ mv History History.bak 
</code></pre><p>再次开打Google Chrome浏览器。</p><h3 id="方法三" tabindex="-1">方法三 <a class="header-anchor" href="#方法三" aria-label="Permalink to “方法三”">​</a></h3><p>如果依然没有解决，你可以试试移除所有默认配置文件夹（~/.config/google-chrome/Default）。注意:如果这样做，你将会遗失所有之前打开的Google标签、导入的书签，浏览记录和登录数据等。</p><p>在移除之前，先关掉所有Chrome窗口和标签页</p><pre><code>$ rm -rf ~/.config/google-chrome/Default
</code></pre><p>之后重启Google Chrome，文件夹~/.config/google-chrome/Default会自动生成。</p><hr>`,21)),n("p",null,[o[1]||(o[1]=e("via: ",-1)),t(r,{href:"http://ask.xmodulo.com/your-profile-could-not-be-opened-correctly-google-chrome.html"},{default:l(()=>[...o[0]||(o[0]=[e("http://ask.xmodulo.com/your-profile-could-not-be-opened-correctly-google-chrome.html",-1)])]),_:1})]),n("p",null,[o[4]||(o[4]=e("译者：",-1)),t(r,{href:"http://vicyu.net"},{default:l(()=>[...o[2]||(o[2]=[e("VicYu/Vic020",-1)])]),_:1}),o[5]||(o[5]=e(" 校对：",-1)),t(r,{href:"https://github.com/carolinewuyan"},{default:l(()=>[...o[3]||(o[3]=[e("Caroline",-1)])]),_:1})]),n("p",null,[o[8]||(o[8]=e("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[6]||(o[6]=[e("LCTT",-1)])]),_:1}),o[9]||(o[9]=e(" 原创翻译，",-1)),t(r,{href:"http://linux.cn/"},{default:l(()=>[...o[7]||(o[7]=[e("Linux中国",-1)])]),_:1}),o[10]||(o[10]=e(" 荣誉推出",-1))])])}const y=i(c,[["render",m]]);export{_ as __pageData,y as default};
